function parseCsv(text) {
  const linhas = [];
  let linha = [];
  let campo = '';
  let entreAspas = false;
  for (let i = 0; i < text.length; i++) {
    const caractere = text[i];
    if (caractere === '"' && entreAspas && text[i + 1] === '"') {
      campo += '"';
      i++;
    } else if (caractere === '"') {
      entreAspas = !entreAspas;
    } else if (caractere === ',' && !entreAspas) {
      linha.push(campo);
      campo = '';
    } else if ((caractere === '\n' || caractere === '\r') && !entreAspas) {
      if (caractere === '\r' && text[i + 1] === '\n') i++;
      linha.push(campo);
      if (linha.some((valor) => valor.trim() !== '')) linhas.push(linha);
      linha = [];
      campo = '';
    } else {
      campo += caractere;
    }
  }
  if (campo || linha.length) {
    linha.push(campo);
    if (linha.some((valor) => valor.trim() !== '')) linhas.push(linha);
  }
  if (linhas.length < 2) throw new Error('O CSV não contém linhas de investimento.');
  const cabecalhos = linhas.shift().map((valor) => valor.trim().replace(/^\uFEFF/, ''));
  const esperados = ['perfil', 'produto', 'minimo', 'rentabilidade'];
  if (esperados.some((campoEsperado) => !cabecalhos.includes(campoEsperado))) {
    throw new Error('Cabeçalhos do CSV inválidos; esperados: perfil,produto,minimo,rentabilidade.');
  }
  const investimentos = linhas.map((valores) => {
    const registro = Object.fromEntries(cabecalhos.map((cabecalho, indice) => [cabecalho, (valores[indice] || '').trim()]));
    const minimo = Number(registro.minimo);
    if (!registro.perfil || !registro.produto || !Number.isFinite(minimo)) {
      throw new Error('Registro inválido no CSV de investimentos.');
    }
    return { ...registro, minimo };
  });
  return investimentos;
}
const resposta = $input.first().json;
const csv = resposta.data ?? resposta.body ?? resposta;
if (typeof csv !== 'string') throw new Error('A resposta HTTP do CSV não é texto.');
return [{ json: { investimentos: parseCsv(csv) } }];

const clientes = $('Separar clientes').all().map((item) => item.json);
const investimentos = $('Converter CSV para JSON').first().json.investimentos;
if (!Array.isArray(clientes) || clientes.length === 0) throw new Error('O webhook não recebeu clientes.');
if (!Array.isArray(investimentos) || investimentos.length === 0) throw new Error('Não há investimentos para cruzar.');
return clientes.map((cliente) => {
  const saldo = Number(cliente.saldo);
  if (!cliente.nome || !cliente.email || !cliente.perfil || !Number.isFinite(saldo)) {
    throw new Error(`Dados inválidos para o cliente ${cliente.nome || '(sem nome)'}.`);
  }
  const ativos = investimentos.filter((opcao) => opcao.perfil === cliente.perfil && opcao.minimo <= saldo);
  return { json: { cliente: { ...cliente, saldo }, ativos } };
});

const preparados = $('Cruzar perfil e saldo').all();
const respostas = $input.all();
function mensagemEstatica(cliente, ativos) {
  const saudacao = `Olá, ${cliente.nome}! Considerando seu perfil ${cliente.perfil} e o saldo informado de R$ ${cliente.saldo.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}, `;
  if (ativos.length === 0) return saudacao + 'não encontramos opções da base cujo investimento mínimo caiba no saldo atual. Você pode rever as alternativas quando seu planejamento mudar.';
  const produtos = ativos.map((ativo) => `${ativo.produto} (mínimo R$ ${ativo.minimo.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}; rentabilidade indicada: ${ativo.rentabilidade})`).join('; ');
  return saudacao + `estas opções da base são compatíveis com o valor mínimo: ${produtos}. Avalie riscos e condições antes de investir; rentabilidade indicada não garante resultados futuros.`;
}
return preparados.map((item, indice) => {
  const dado = item.json;
  const respostaIa = respostas[indice]?.json || {};
  const gerada = [respostaIa.output, respostaIa.text, respostaIa.response].find((valor) => typeof valor === 'string' && valor.trim());
  const cliente = dado.cliente;
  const ativos = dado.ativos;
  return { json: {
    cliente,
    ativos_recomendados: ativos,
    mensagem: gerada ? gerada.trim() : mensagemEstatica(cliente, ativos),
    fonte_mensagem: gerada ? 'ia' : 'template_fallback'
  } };
});
